   117	const GROUP_ID = /^[a-z][a-z0-9-]{0,29}$/
   118	const MEMBER_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,29}$/
   119	const MIN_MEMBERS = 2
   120	const MAX_MEMBERS = 20
   121	const MAX_GROUP_NAME_LENGTH = 100
   122	const MAX_DESCRIPTION_LENGTH = 200
   123	const CENTS_PER_UNIT = 100
   124	const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
   125	// Digits with at most two decimals, as String() writes a number: "12", "12.5", "4.35".
   126	const TWO_DECIMALS = /^[0-9]+(\.[0-9]{1,2})?$/
   127	
   128	const AMOUNT_MESSAGE = 'amount must be a number from 0.01 to 1000000 with at most 2 decimals'
   129	const SPLIT_MESSAGE = 'split must be a non-empty list of different members of the group'
   130	
   131	const isText = (v, max) => typeof v === 'string' && v.trim() !== '' && v.length <= max
   132	
   133	export function parseGroupId(v) {
   134	  if (typeof v !== 'string' || !GROUP_ID.test(v)) {
   135	    throw new ValidationError('id must be 1 to 30 characters of a-z, 0-9 or -, starting with a letter')
   136	  }
   137	  return v
   138	}
