   140	export function parseGroupName(v) {
   141	  if (!isText(v, MAX_GROUP_NAME_LENGTH)) {
   142	    throw new ValidationError(`name must be a non-empty string of at most ${MAX_GROUP_NAME_LENGTH} characters`)
   143	  }
   144	  return v
   145	}
