   147	// A list of 2 to 20 member names, each used once. Names are case-sensitive: "Ann" and "ann" are two people.
   148	export function parseMembers(v) {
   149	  if (!Array.isArray(v) || v.length < MIN_MEMBERS || v.length > MAX_MEMBERS) {
   150	    throw new ValidationError(`members must be an array of ${MIN_MEMBERS} to ${MAX_MEMBERS} names`)
   151	  }
   152	  if (!v.every(name => typeof name === 'string' && MEMBER_NAME.test(name))) {
   153	    throw new ValidationError('member names must be 1 to 30 characters of A-Z, a-z, 0-9, _ or -, starting with a letter')
   154	  }
   155	  if (new Set(v).size !== v.length) throw new ValidationError('members must not repeat a name')
   156	  return [...v]
   157	}
   158	
   159	export function parseDescription(v) {
   160	  if (!isText(v, MAX_DESCRIPTION_LENGTH)) {
   161	    throw new ValidationError(`description must be a non-empty string of at most ${MAX_DESCRIPTION_LENGTH} characters`)
   162	  }
   163	  return v
   164	}
