   181	// Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
   182	export function parseSplit(v, members) {
   183	  if (v === undefined) return [...members]
   184	  if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
   185	  if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
   186	  return [...v]
   187	}
   188	// Money maths on whole cents: how an expense is shared, what each member is owed or owes, and how to settle up.
   189	// Amounts are stored as cents and shown by the API as numbers (435 cents is 4.35).
   190	
   191	const CENTS_PER_UNIT = 100
   192	
   193	export const toAmount = cents => cents / CENTS_PER_UNIT
   194	
   195	// Each person's part of an amount in cents, as [name, cents] pairs in the order of people. When the amount does
   196	// not divide evenly, the first people pay one cent more each, so the parts always add up to the amount.
   197	export function splitEvenly(cents, people) {
   198	  const share = Math.floor(cents / people.length)
   199	  const remainder = cents - share * people.length
   200	  return people.map((name, i) => [name, share + (i < remainder ? 1 : 0)])
   201	}
   202	
   203	// An expense as the API shows it: amounts as numbers, plus each person's share keyed by name.
   204	export function expenseView({ id, description, payer, amount, split }) {
   205	  const shares = Object.fromEntries(splitEvenly(amount, split).map(([name, cents]) => [name, toAmount(cents)]))
   206	  return { id, description, payer, amount: toAmount(amount), split, shares }
   207	}
   208	
   209	export const paymentView = ({ id, from, to, amount }) => ({ id, from, to, amount: toAmount(amount) })
   210	
   211	// Each member's balance in cents, as a Map in the group's member order. A payer is owed the whole expense
   212	// minus their own share; a payment from A to B moves A up and B down.
   213	function balanceCents(state, group) {
   214	  const cents = new Map(group.members.map(name => [name, 0]))
   215	  const add = (name, delta) => cents.set(name, cents.get(name) + delta)
   216	  for (const expense of state.expenses.filter(e => e.group === group.id)) {
   217	    add(expense.payer, expense.amount)
   218	    for (const [name, share] of splitEvenly(expense.amount, expense.split)) add(name, -share)
   219	  }
   220	  for (const payment of state.payments.filter(p => p.group === group.id)) {
   221	    add(payment.from, payment.amount)
   222	    add(payment.to, -payment.amount)
   223	  }
   224	  return cents
   225	}
   226	
   227	// What each member of the group is owed (positive) or owes (negative), in the group's member order.
   228	export function balances(state, group) {
   229	  return Object.fromEntries([...balanceCents(state, group)].map(([name, cents]) => [name, toAmount(cents)]))
   230	}
   231	
   232	// The member furthest on one side: sign 1 is owed the most, sign -1 owes the most. Ties go to the member who
   233	// comes first in the map; null when nobody is on that side.
   234	function furthest(cents, sign) {
   235	  let best = null
   236	  for (const [name, value] of cents) {
   237	    if (value * sign > 0 && (best === null || value * sign > cents.get(best) * sign)) best = name
   238	  }
   239	  return best
   240	}
   241	
   242	// Payments that would bring every balance to 0, as [{from, to, amount}]: the member who owes the most pays the
   243	// member who is owed the most whichever is smaller of the two, until nobody owes anything.
   244	export function settleUp(state, group) {
   245	  const left = balanceCents(state, group)
   246	  const payments = []
   247	  let from = furthest(left, -1)
   248	  let to = furthest(left, 1)
   249	  while (from && to) {
   250	    const cents = Math.min(-left.get(from), left.get(to))
   251	    payments.push({ from, to, amount: toAmount(cents) })
   252	    left.set(from, left.get(from) + cents)
   253	    left.set(to, left.get(to) - cents)
   254	    from = furthest(left, -1)
   255	    to = furthest(left, 1)
   256	  }
   257	  return payments
   258	}
   259	// HTTP entry point: finds the route, reads the JSON body of the routes that take one, runs the handler and
   260	// saves the store after every change. Env: PORT (default 3000), DATA_FILE (default groups.json).
   261	import { existsSync } from 'node:fs'
   262	import { createServer } from 'node:http'
   263	import { dirname, resolve } from 'node:path'
   264	import { errorReply, parseJsonObject, readBody, send } from './lib/http.mjs'
   265	import { findRoute } from './lib/routes.mjs'
   266	import { load, save } from './lib/store.mjs'
   267	
   268	const DEFAULT_PORT = 3000
   269	const MAX_PORT = 65535
   270	
   271	// Builds the server around the store in dataFile. The store is kept in memory; each change is saved before it
   272	// replaces the in-memory copy, so a failed save changes nothing.
   273	export function createApp(dataFile) {
   274	  let state = load(dataFile)
   275	  return createServer(async (req, res) => {
   276	    try {
   277	      // Prefixing the origin keeps a request path like //host/groups a path, not a host.
   278	      const url = new URL(`http://localhost${req.url}`)
   279	      const route = findRoute(req.method, url.pathname)
   280	      if (!route) return send(res, { status: 404, body: { error: 'not found' } })
   281	      const body = route.takesBody ? parseJsonObject(await readBody(req)) : undefined
   282	      const reply = route.handler({ state, params: route.params, query: url.searchParams, body })
   283	      if (reply.state) {
   284	        save(dataFile, reply.state)
   285	        state = reply.state
   286	      }
   287	      send(res, reply)
   288	    } catch (err) {
   289	      send(res, errorReply(err))
   290	    }
   291	  })
   292	}
