   299	// A plain message for the OS errors a bad DATA_FILE gives; any other error keeps its own.
   300	function loadErrorMessage(err, file) {
   301	  if (err.code === 'EISDIR') return `DATA_FILE ${file} is a folder, not a file`
   302	  if (err.code === 'EACCES') return `cannot read DATA_FILE ${file}: permission denied`
