   339	// Reads the store from file. A missing file is an empty store; a damaged file is an error.
   340	export function load(file) {
   341	  let text
   342	  try {
   343	    text = readFileSync(file, 'utf8')
   344	  } catch (err) {
   345	    if (err.code === 'ENOENT') return emptyStore()
