   358	// Writes the store atomically: a temp file next to the target, then a rename over it.
   359	export function save(file, data) {
   360	  const tmp = `${file}.${process.pid}.tmp`
   361	  writeFileSync(tmp, JSON.stringify(data, null, 2) + '\n')
   362	  try {
   363	    renameSync(tmp, file)
   364	  } catch (err) {
   365	    rmSync(tmp, { force: true })
   366	    throw err
   367	  }
